// --- Step 1: 解析来自上游节点的JSON字符串 ---
// (这部分和您的代码逻辑一致)
const jsonString = $input.item.json.output;
const jsonArray = JSON.parse(jsonString);

// --- Step 2: 遍历、拆分并构建结构化的新对象 ---
// 我们继续使用 .map() 方法，但在返回的对象中加入拆分后的新字段
const formattedArray = jsonArray.map(topicObject => {
  // 找出每个对象中那个动态的键名 (例如 "topic_1", "topic_2")
  const dynamicKey = Object.keys(topicObject)[0];

  // 获取该键名对应的值 (即包含1-6部分的完整选题内容)
  const topicContent = topicObject[dynamicKey];

  // --- 新增逻辑：使用正则表达式进行拆分 ---

  // 1. 定义用于拆分的正则表达式
  //    - coreTopicRegex: 匹配从开头到“5. 战略定位”之前的所有内容
  //    - strategicLevelRegex: 匹配“5. 战略定位”和“6. 用户画像与核心目标”之间的内容
  //    - userPersonaRegex: 匹配“6. 用户画像与核心目标”之后的所有内容
  const coreTopicRegex = /^([\s\S]*)\n5\. 战略定位/;
  const strategicLevelRegex = /5\. 战略定位\n([\s\S]*?)\n6\. 用户画像与核心目标/;
  const userPersonaRegex = /6\. 用户画像与核心目标\n([\s\S]*)$/;

  // 2. 执行匹配并提取内容
  //    - .match() 会返回一个数组，我们需要的捕获内容在索引[1]
  //    - `?.` (可选链) 和 `?? ''` (空值合并) 用于防止因内容格式不匹配导致流程报错，如果没匹配到就返回空字符串，非常安全。
  //    - .trim() 用于去除提取内容两端的空行和空格
  const coreTopic = topicContent.match(coreTopicRegex)?.[1]?.trim() ?? '';
  const strategicLevel = topicContent.match(strategicLevelRegex)?.[1]?.trim() ?? '';
  const userPersona = topicContent.match(userPersonaRegex)?.[1]?.trim() ?? '';

  // --- 更新返回的对象结构 ---
  // 返回一个包含原始Key和所有拆分后字段的新对象
  return {
    topicKey: dynamicKey,
    coreTopic: coreTopic,              // 新增：核心选题方向 (1-4部分)
    strategicLevel: strategicLevel,    // 新增：战略定位 (第5部分)
    userPersona: userPersona,          // 新增：用户画像与核心目标 (第6部分)
    originalContent: topicContent      // 保留原始长文本，方便调试或后续使用
  };
});

// --- Step 3: 返回包含所有结构化数据的新数组 ---
// n8n 会自动将这个新数组中的每一个对象，都转换成一个独立的Item
return formattedArray;

